import base64,os,subprocess,ast
code=base64.b64decode("").decode("utf-8")
ast.parse(code)
open("/content/fly/lif_dose.py","w",encoding="utf-8").write(code)
ps=subprocess.run("ps -eo pid,cmd | grep '[l]if_dose.py'",shell=True,capture_output=True,text=True).stdout.strip()
print("running:",ps or "(none)")
if not ps:
    subprocess.Popen("nohup python -u /content/fly/lif_dose.py > /content/fly/dose.log 2>&1 &",shell=True,executable="/bin/bash")
    print("LAUNCHED")
